$(document).ready(function(){var t=$("#country"),n=$("#state"),o="",i="";t.change(a=>{t.val()!=""&&c()}),t.find(":selected").val()!=""&&c();function c(){o=t.val(),i=n.val(),n.empty(),n.append('<option disabled selected value="">-Seleccionar una opcion-</option>'),$.ajax({type:"get",url:location.origin+"/api/state/"+o,success:function(a){$.each(a,function(r,e){i==e.name?n.append('<option selected value="'+e.name+'">'+e.name+"</option>"):n.append('<option value="'+e.name+'">'+e.name+"</option>")})},error:function(a,r,e){console.error("Error fetching states: ",e),n.append('<option value="">Error al cargar provincias</option>')}})}});
